INSERT INTO resource (name, category, service_type, provider_type, org_name, dept_name, phone, support_content, apply_method, apply_url, age_min, age_max, income_uncertain, disability, nationality, uncertain_note, eligibility_raw, service_cycle, source_name, source_url, data_base_date, last_verified_date, status) VALUES ('효도수당', 'DAILY', '현금', 'PUB', '시흥시청', '복지국 노인복지과', '031-310-2265', '효도수당 매월 3만원 지원', '방문, 인터넷 — 1) 효도수당을 지급받고자 하는 사람은 별지 제1호 서식에 의한 신청서를 관할 동 주민센터 제출하여야 한다. 2) 동장은 관계공무원으로 하여금 신청서의 내용을 확인 후 신청서류 일체를 시장에게 제출하여야 한다. 3) 시장은 지급대상자를 확정하여 개인별 금융계좌로 수당을 지급한다. 4) 효도수당은 신청한 달부터 지급하고, 제6조의 규정에 따라 지급중지사유 발생 시에는 그 사유가 발생한 달까지 지급한다.5) 효도수당 지급 대상자는 지급중지사유 발생 시 해당 동으로 그 사유를 신고해야하며, 신고치 아니하여 지급된 수당은 추후 환수조치 할 수 있다.', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00001391&wlfareInfoReldBztpCd=02', 70, NULL, NULL, NULL, NULL, '복지로 API 수집분(2026) — 대상: 다음의 2가지를 만족하는 대상자 1) 3세대 가족 구성원이 함께 시흥시에 5년 이상 주소를 두고 계속하여 거주할 것 2) 1세대가 만 70세 이상일 것', '다음의 2가지를 만족하는 대상자 1) 3세대 가족 구성원이 함께 시흥시에 5년 이상 주소를 두고 계속하여 거주할 것 2) 1세대가 만 70세 이상일 것 만 70세 이상 이상 직계존속, 직계비속과 관내 5년 이상 계속하여 함께 거주하고 있는 3세대 가구', '월', '복지로 지자체복지서비스 API', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00001391&wlfareInfoReldBztpCd=02', '2026-08-15', '2026-10-14', 'A');
