INSERT INTO resource (name, category, service_type, provider_type, org_name, dept_name, phone, support_content, apply_method, apply_url, age_min, age_max, income_uncertain, disability, nationality, uncertain_note, eligibility_raw, service_cycle, source_name, source_url, data_base_date, last_verified_date, status) VALUES ('(경기도 외 타시도)중, 고등학교 신입생 교복비 지원사업', 'EDU', '현금', 'PUB', '시흥시청', '평생교육원 교육자치과', '031-310-3496', '· 400,000원 이내 현금 지원(학칙 등에 규정된 교복 및 단체복 등) - 단, 다른 시ㆍ도 또는 기관 등에서 교복 또는 입학지원금 등을 지원받을 수 있는 경우, 해당 지자체 교육청 우선 지원이 원칙이며 지자체 ‘지원상한액’의 차액만큼만 지원 가능(예시) 강원도에서 교복지원금 200,000원 받은 경기도민 학생  → 경기도 지원금 400,000원 - 강원도 상한액 336,000원 = [64,000원 차액 지원] (O)  → 경기도 지원금 400,000원 - 강원도 지원액 200,000원 = [200,000원 지원?]     (X)', '인터넷 — · 신청기간 : 2026. 3. 9. ~ 2026. 12. 11. - 예산 소진 시 당해연도 지급 불가 다음년도에 지급 예정· 신청방법 : 온라인(경기민원24)', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00003851&wlfareInfoReldBztpCd=02', NULL, NULL, NULL, NULL, NULL, '복지로 API 수집분(2026) — 대상: (타 시도 소재) 중·고등학교 1학년 입학생(입학일 현재 시흥시 주민)', '(타 시도 소재) 중·고등학교 1학년 입학생(입학일 현재 시흥시 주민) 입학일 현재 시흥시에 주민등록이 되어있으며, (타 시도 소재)중·고등학교 1학년 입학생- 다른 지자체 및 기관에서 지원을 받은경우 지원불가', '1회성', '복지로 지자체복지서비스 API', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00003851&wlfareInfoReldBztpCd=02', '2026-08-15', '2026-10-14', 'A');
INSERT INTO resource (name, category, service_type, provider_type, org_name, dept_name, phone, support_content, apply_method, apply_url, age_min, age_max, income_uncertain, disability, nationality, uncertain_note, eligibility_raw, service_cycle, source_name, source_url, data_base_date, last_verified_date, status) VALUES ('시흥시 국가보훈대상자 지원', 'DAILY', '현금', 'PUB', '시흥시청', '복지국 복지정책과', '031-310-3553', '1) 보훈명예수당.참전유공자 명예수당 - 지급대상 : 관내거주 국가보훈대상자 - 지급금액 : 65세 이상 월 10만원, 65세 미만 월 7만원   ※ 80세 이상 참전유공자 참전 명예수당 추가지급 : 월 5만원2) 사망참전유공자 배우자수당 - 지급대상 : 사망 참전유공자의 배우자 - 지급금액 : 65세 이상 월 5만원, 65세 미만 월 3만5천원3) 국가유공자 위문금  - 지급대상 : 관내거주 국가보훈대상자 - 지급금액 : 5만원/연3회   4) 독립유공자 및 유족 특별위로금 - 지급대상 : 순국선열·애국지사유족등 관내거주 국가보훈대상자 중 독립유공자 본인 및 선순위 유족 - 지급금액 : 20만원/연2회5) 국가유공자 사망위로금 - 지급대상 : 관내거주 국가보훈대상자 중 사망자 - 지 급 액 : 15만원/1회 (사망일로부터 1년이내 신청)6) 국가유공자 장수축하금 - 지급대상 : 관내거주 국가보훈대상자 중 100세 도달 대상자 - 지 급 액 : 100만원(100세 도달 시, 1회)', '방문 — 1) 보훈명예수당. 참전명예수당 - 신청방법 : 거주지 관할 동주민센터 신청 - 지급방법 : 수급자 계좌에 시/군/구청장이 직접 입금2) 사망참전유공자 배우자수당 - 신청방법 : 거주지 관할 동주민센터 신청 - 지급방법 : 수급자 계좌에 시/군/구청장이 직접 입금3) 국가유공자 위문금 - 신청방법 : 주소지 관할 동주민센터 신청 / 보훈처 조회결과 국가유공자인 경우 지급 - 지급방법 : 수급자 계좌에 시/군/구청장이 직접 입금   4) 독립유공자 및 유족 특별위로금 - 신청방법 : 주소지 관할 동주민센터 신청 / 보훈처 조회결과 국가유공자인 경우 지급(독립유공자 본인 및 선순위 유족) - 지급방법 : 수급자 계좌에 시/군/구청장이 직접 입금5) 국가유공자 사망위로금 - 신청방법 : 사망자 거주지 동주민센터 방문 신청 - 제출서류 : 사망진단서, 사망자 국가유공자증, 가족관계확인서, 신청자 신분증, 통장사본6) 국가유공자 장수축하금 - 신청방법 : 직접 지원(기존 지원 국가보훈대상자 별도 신청 불요) - 지급방법 : 수급자 계좌에 시/군/구청장이 직접 입금', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00004050&wlfareInfoReldBztpCd=02', NULL, NULL, NULL, NULL, NULL, '복지로 API 수집분(2026) — 대상: 국가를 위하여 희생하거나 공헌한 관내 국가유공자 및 그 유족', '국가를 위하여 희생하거나 공헌한 관내 국가유공자 및 그 유족 국가보훈대상자', '월', '복지로 지자체복지서비스 API', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00004050&wlfareInfoReldBztpCd=02', '2025-05-31', '2026-10-14', 'A');
INSERT INTO resource (name, category, service_type, provider_type, org_name, dept_name, phone, support_content, apply_method, apply_url, age_min, age_max, income_uncertain, disability, nationality, uncertain_note, eligibility_raw, service_cycle, source_name, source_url, data_base_date, last_verified_date, status) VALUES ('취약계층 인플루엔자 예방접종 지원사업', 'HEALTH', '기타서비스', 'PUB', '시흥시청', '보건소 감염병관리과', '031-380-5815', '인플루엔자 예방접종 지원사업· 계절인플루엔자(독감) 예방접종 1회 무료 지원· 지정의료기관에서 무료 접종 가능(기관은 보건소/보건지소에 전화해서 확인)', '', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00004481&wlfareInfoReldBztpCd=02', NULL, NULL, 'Y', NULL, NULL, '복지로 API 수집분(2026) — 대상: 만 50~64세 출생자 중 기초생활수급자 또는 장애의 정도가 심한 장애에 해당하는 자', '만 50~64세 출생자 중 기초생활수급자 또는 장애의 정도가 심한 장애에 해당하는 자 연령 : 만 50~64세 성인「장애인복지법」에 따른 장애의 정도가 심한 장애인「국민기초생활보장법」에 따른 수급자', '1회성', '복지로 지자체복지서비스 API', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00004481&wlfareInfoReldBztpCd=02', '2026-09-03', '2026-10-14', 'A');
INSERT INTO resource (name, category, service_type, provider_type, org_name, dept_name, phone, support_content, apply_method, apply_url, age_min, age_max, income_uncertain, disability, nationality, uncertain_note, eligibility_raw, service_cycle, source_name, source_url, data_base_date, last_verified_date, status) VALUES ('시흥형 기본교통비 지원 사업', 'DAILY', '바우처', 'PUB', '시흥시청', '안전교통국 대중교통과', '031-310-2756,2759', '대중교통 이용 실적에 따른 교통비 분기별 지역화폐 지급 - 6~18세는 경기도 분기 6만원-11~18세 시흥시 분기 12만원 추가 지급', '인터넷 — 2025년 6월까지 시흥형 기본교통비 홈페이지 회원가입 후 교통카드 신청2025년 7월부터 경기도 청소년 교통비 사업과 통합운영함에 따라 경기도홈페이지 회원가입 후 신청', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00004680&wlfareInfoReldBztpCd=02', NULL, NULL, NULL, NULL, NULL, '복지로 API 수집분(2026) — 대상: 시흥시에 주민등록이 되어있는 11세~18세', '시흥시에 주민등록이 되어있는 11세~18세 시흥시에 주민등록을 두고 있는 11세~18세', '분기', '복지로 지자체복지서비스 API', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00004680&wlfareInfoReldBztpCd=02', '2026-07-23', '2026-10-14', 'A');
INSERT INTO resource (name, category, service_type, provider_type, org_name, dept_name, phone, support_content, apply_method, apply_url, age_min, age_max, income_uncertain, disability, nationality, uncertain_note, eligibility_raw, service_cycle, source_name, source_url, data_base_date, last_verified_date, status) VALUES ('장애학생 교내활동지원 사업', 'EDU', '현금', 'PUB', '시흥시청', '복지국 장애인복지과', '031-310-6865', '1시간당 19,620원', '방문 — - 행정복지센터에 방문하여 신청서류 작성', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00004715&wlfareInfoReldBztpCd=02', NULL, NULL, 'Y', NULL, NULL, '복지로 API 수집분(2026) — 대상: 특수교육대상자로 선정된 초·중·고 장애학생(장애인활동지원 기 수급자) 중 학급 내 활동지원사 지원을 신청한 학생', '특수교육대상자로 선정된 초·중·고 장애학생(장애인활동지원 기 수급자) 중 학급 내 활동지원사 지원을 신청한 학생 신청자의 개인 행동 평정 및 돌봄인력 배치점수를 합산하여, 상위점수 순으로 선정', '월', '복지로 지자체복지서비스 API', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00004715&wlfareInfoReldBztpCd=02', '2026-07-29', '2026-10-14', 'A');
INSERT INTO resource (name, category, service_type, provider_type, org_name, dept_name, phone, support_content, apply_method, apply_url, age_min, age_max, income_uncertain, disability, nationality, uncertain_note, eligibility_raw, service_cycle, source_name, source_url, data_base_date, last_verified_date, status) VALUES ('시흥시 노동취약계층 유급병가 지원사업', 'DAILY', '현금', 'PUB', '시흥시청', '경제국 노동지원과', '031-310-3984', '입원치료 및 건강검진 일수에 따라 유급병가비(생계비) 지급', '방문, 우편 — ☞ 신청방법 : 노동지원과 방문 제출 또는 등기우편 제출☞ 지급방법 : 대상자 계좌에 현금 입금', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00004964&wlfareInfoReldBztpCd=02', NULL, NULL, 'Y', NULL, NULL, '복지로 API 수집분(2026) — 대상: 입원치료 또는 공단 일반 건강검진을 받은 시흥시 거주 노동취약계층', '입원치료 또는 공단 일반 건강검진을 받은 시흥시 거주 노동취약계층                ① 2026년 입원치료 또는 국민건강보험공단 일반건강검진을 받은 사람       ※ 입원(검진)자는 퇴원일로 부터 6개월 이내 신청       ※ 2025년 9~12월 입원(검진)자는 연도와 관계없이 퇴원일로부터 6개월 이내 신청가능)   ② 입원 또는 건강검진 기간 동안 국민건강보험 지역가입자인 사람   ③ 시흥시에 주민등록 신고된 사람(입원일(검진일) 기준 30일 전부터 지급완료일까지)   ④ 근로소득자 또는 사업소득자인 사람      (입원(검진)일 기준 3개월 동안 근로자는 24일 이상 근로, 사업자는 45일 이상 사업장 유지)   ⑤ 기준 중위소득 120% 이하인 사람     ☞ 국민기초생활보장(생계급여), 긴급복지(생계급여), 실업급여·산재보험 수혜자 지원 제외', '1회성', '복지로 지자체복지서비스 API', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00004964&wlfareInfoReldBztpCd=02', '2026-07-11', '2026-10-14', 'A');
INSERT INTO resource (name, category, service_type, provider_type, org_name, dept_name, phone, support_content, apply_method, apply_url, age_min, age_max, income_uncertain, disability, nationality, uncertain_note, eligibility_raw, service_cycle, source_name, source_url, data_base_date, last_verified_date, status) VALUES ('누구나 돌봄! 시흥돌봄SOS센터 운영', 'HEALTH', '프로그램', 'PUB', '시흥시청', '복지국 통합돌봄과', '031-310-3568', '□ 사업내용: 다양한 돌봄욕구 대응을 위한 13대 돌봄서비스 지원 ○ 7대 단기 돌봄서비스(수가체계)   - 생활돌봄: 대상자 가정방문을 통한 신체·가사활동 지원   - 동행돌봄: 필수적 외출 활동 동행지원   - 주거안전: 간단 집수리, 청소, 방역 및 세탁서비스   - 식사지원: 기본적인 식생활 유지를 위한 식사 배달   - 일시보호: 단기 시설입소를 통한 보호와 수발   - 재활돌봄: 운동재활 및 일상생활 수행훈련   - 심리상담: 심리·정서적 어려움에 대한 상담 지원 ○ 6대 중장기 돌봄연계(비수가체계)   - 안부확인, 건강지원, 돌봄제도, 사례관리, 긴급지원, 주거편의', '방문, 전화 — □ 이용방법: 주소지 동 행정복지센터(돌봄SOS센터) 방문 또는 전화', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00005239&wlfareInfoReldBztpCd=02', NULL, NULL, 'Y', NULL, NULL, '복지로 API 수집분(2026) — 대상: 돌봄공백 등 위기상황으로 돌봄이 필요한 시민', '돌봄공백 등 위기상황으로 돌봄이 필요한 시민 □ 돌봄 적격판단 기준(적정성 검토) ○ 혼자 거동하기 어렵거나 독립적인 일상생활 수행이 어려운 경우 ○ 수발할 수 있는 가족 등이 부재하거나 수발할 수 없는 경우 ○ 공적 돌봄서비스를 이용하지 않거나 서비스 이용 중 불가피한 공백이 발생한 경우  ※ 위 세가지 기준을 기본으로 돌봄 필요성을 종합적으로 확인하여 지원여부 결정□ 비용지원 ○ 기초수급자·차상위계층·기준중위소득 120%이하 전액지원, 120%초과~150%이하 50%지원, 150%초과 자부담 ○ 「국가유공자 등 예우 및 지원에 관한 법률」 제4조에 따른 국가유공자 본인 및 선순위 유족 전액지원', '수시', '복지로 지자체복지서비스 API', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00005239&wlfareInfoReldBztpCd=02', '2026-08-15', '2026-10-14', 'A');
INSERT INTO resource (name, category, service_type, provider_type, org_name, dept_name, phone, support_content, apply_method, apply_url, age_min, age_max, income_uncertain, disability, nationality, uncertain_note, eligibility_raw, service_cycle, source_name, source_url, data_base_date, last_verified_date, status) VALUES ('출생축하금 지원', 'CARE', '현금', 'PUB', '시흥시청', '보건소 보건정책과', '031-310-5850,5878', '- 2022.1월생 ~ 2023.12월생 : 첫째~셋째(미지원), 넷째아 이상(200만원/4년 분할)- 2025년생(출생신고일로부터 12개월 이내 영아): 첫째(미지원), 둘째(50만원), 셋째(100만원), 넷째아 이상(200만원/4년 분할)- 2026년생: 첫째(50만원), 둘째(100만원), 셋째(200만원), 넷째아 이상(200만원/4년 분할)', '방문 — 신생아 출생신고일 등을 기준으로 60일 이내에 동 행정복지센터에 신청', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00005386&wlfareInfoReldBztpCd=02', NULL, NULL, NULL, NULL, NULL, '복지로 API 수집분(2026) — 대상: 지원대상 : 출생아의 출생신고일 기준으로 부 또는 모가 시에 주민등록을 두고 180일 이전부터 거주한 사람', '지원대상 : 출생아의 출생신고일 기준으로 부 또는 모가 시에 주민등록을 두고 180일 이전부터 거주한 사람            출생아의 출생신고일 기준으로 부 또는 모가 시에 주민등록을 두고 180일 이전부터 거주한 사람(단, 출생신고일 등을 기준으로 180일 미만 거주자는 180일이 경과할 때까지 주민등록을 두고 거주한 경우 지원 가능)', '년', '복지로 지자체복지서비스 API', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00005386&wlfareInfoReldBztpCd=02', '2026-06-30', '2026-10-14', 'A');
